<?php
declare(strict_types=1);
/**
 * install_mrl_profile_redesign.php
 * VERSION: v003
 * LAST MODIFIED: 8/27/2026 9:24:30 pm
 */
date_default_timezone_set('America/New_York');
const EXPECTED_PROFILE_SHA256='4543ae7da508cbf8c6d17c45d214ba11c3c8d87f7261ec08863447b7083e44be';
$base=__DIR__;
$profile=$base.'/profile_redesign.php';
$teamRedesign=$base.'/team_redesign.php';
$helper=$base.'/mrl_team/mrl_theme_helper.php';
$json=$base.'/mrl_team/mrl_team_page_content.json';
$manager=$base.'/mrl_team/admin_team_page_content.php';
$prodTeam=$base.'/team.php';
$prodProfile=$base.'/profile.php';
$oldLogin=$base.'/change-login-email.php';
$oldSecond=$base.'/change-second-email.php';
function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function sr(string $l,bool $ok,string $d=''):void{echo '<tr><td>'.h($l).'</td><td class="'.($ok?'ok':'bad').'">'.($ok?'PASS':'FAIL').'</td><td>'.h($d).'</td></tr>';}
function aw(string $p,string $d):bool{$t=$p.'.tmp_'.bin2hex(random_bytes(4));if(file_put_contents($t,$d,LOCK_EX)===false)return false;if(!@rename($t,$p)){@unlink($t);return false;}return true;}
$replacement=base64_decode('',true);
$replacementOk=is_string($replacement)
    && strpos($replacement,'VERSION: v003')!==false
    && strpos($replacement,'userSession')!==false
    && strpos($replacement,'save_primary_email')!==false
    && strpos($replacement,'save_secondary_email')!==false
    && strpos($replacement,'save_theme')!==false
    && strpos($replacement,'change-login-email.php')===false
    && strpos($replacement,'change-second-email.php')===false;
$profileExists=is_file($profile);
$profileHash=$profileExists?hash_file('sha256',$profile):'';
$baselineOk=$profileExists&&$profileHash===EXPECTED_PROFILE_SHA256&&strpos((string)file_get_contents($profile),'VERSION: v002')!==false;
$protected=[$teamRedesign,$helper,$json,$manager,$prodTeam,$prodProfile];
$before=[];$protectedOk=true;
foreach($protected as $p){if(!is_file($p)){$protectedOk=false;$before[$p]='';}else{$before[$p]=hash_file('sha256',$p);}}
$oldPagesPresent=is_file($oldLogin)&&is_file($oldSecond);
$apply=isset($_POST['apply'])&&$_POST['apply']==='1';$msgs=[];$success=false;
if($apply&&$replacementOk&&$baselineOk&&$protectedOk){
    $backupDir=$base.'/_migration_backups/profile_redesign_v003_'.date('Ymd_His');
    $ok=(is_dir($backupDir)||mkdir($backupDir,0755,true));
    if(!$ok){$msgs[]='Could not create backup directory.';}
    elseif(!copy($profile,$backupDir.'/profile_redesign.php')){$ok=false;$msgs[]='Could not back up profile_redesign.php.';}
    else{$msgs[]='Backed up exact working profile_redesign.php v002.';}
    if($ok&&!aw($profile,$replacement)){$ok=false;$msgs[]='Could not install profile_redesign.php v003.';}
    elseif($ok){$msgs[]='Installed self-contained profile_redesign.php v003.';}
    if($ok){
        $installed=(string)file_get_contents($profile);
        $checks=[
            'v003 header'=>strpos($installed,'VERSION: v003')!==false,
            'authenticated userSession identity'=>strpos($installed,'userSession')!==false,
            'primary email action'=>strpos($installed,'save_primary_email')!==false,
            'secondary email action'=>strpos($installed,'save_secondary_email')!==false,
            'theme action'=>strpos($installed,'save_theme')!==false,
            'CSRF token'=>strpos($installed,'mrl_profile_csrf')!==false,
            'no login-email page dependency'=>strpos($installed,'change-login-email.php')===false,
            'no secondary-email page dependency'=>strpos($installed,'change-second-email.php')===false,
        ];
        foreach($checks as $label=>$pass){$msgs[]=($pass?'PASS: ':'FAIL: ').$label;if(!$pass)$ok=false;}
    }
    foreach($before as $p=>$hash){$same=$hash!==''&&is_file($p)&&$hash===hash_file('sha256',$p);$msgs[]=($same?'Verified unchanged: ':'ERROR changed: ').str_replace($base.'/','',$p);if(!$same)$ok=false;}
    $msgs[]=$oldPagesPresent?'Legacy email-change pages remain on disk for rollback/reference; v003 does not use them.':'Legacy email-change pages were already absent; no deletion attempted.';
    $success=$ok;
}
?><!doctype html><html><head><meta charset="utf-8"><title>MRL Profile Redesign Installer v003</title><style>*{box-sizing:border-box}html{background:#111}body{margin:0;color:#eee;font-family:Tahoma,Verdana,Segoe UI,sans-serif}.wrap{width:94%;max-width:1150px;margin:20px auto}.card{background:#202020;border:1px solid #555;border-radius:14px;padding:20px;margin-bottom:16px}h1,h2{color:#efc982}table{width:100%;border-collapse:collapse}td{padding:9px;border-bottom:1px solid #444}.ok{color:#61e493}.bad{color:#ff7777}button{padding:11px 20px;background:#1466c9;color:#fff;border:1px solid #5a7fb5;border-radius:9px;font-weight:800}a,code{color:#76cfff}li{line-height:1.45;margin-bottom:5px}</style></head><body><div class="wrap">
<div class="card"><h1>MRL Profile Redesign Installer v003</h1><p>Integrates Login Email, Secondary Email and Theme into one authenticated Profile page.</p></div>
<div class="card"><h2>Preflight</h2><table><?php sr('Exact profile_redesign.php v002 baseline',$baselineOk,$profileHash); ?><?php sr('Complete v003 replacement embedded',$replacementOk,'Full-file replacement.'); ?><?php sr('Protected Team/support/production files present',$protectedOk,'Six files checked.'); ?><?php sr('Legacy email pages currently present',$oldPagesPresent,'Kept for rollback/reference; not used by v003.'); ?></table></div>
<?php if($baselineOk&&$replacementOk&&$protectedOk): ?><div class="card"><h2>What v003 changes</h2><ul><li>Login Email is edited directly on Profile.</li><li>Secondary Email is edited directly on Profile; blank + Save removes it.</li><li>User identity comes only from authenticated <code>userSession</code>.</li><li>All profile writes use CSRF protection.</li><li>The old standalone email pages are no longer linked or required.</li><li>The old pages are deliberately left on disk until testing is complete.</li><li>Production <code>profile.php</code> and <code>team.php</code> remain untouched.</li></ul><?php if(!$apply): ?><form method="post"><input type="hidden" name="apply" value="1"><button>Install Profile Redesign v003</button></form><?php endif; ?></div><?php endif; ?>
<?php if($apply): ?><div class="card"><h2>Apply Result</h2><p class="<?php echo $success?'ok':'bad'; ?>"><strong><?php echo $success?'SUCCESS':'FAILED'; ?></strong></p><ul><?php foreach($msgs as $m): ?><li><?php echo h($m); ?></li><?php endforeach; ?></ul><?php if($success): ?><p><a href="/profile_redesign.php" target="_blank">Open Profile Redesign v003</a></p><?php endif; ?></div><?php endif; ?>
</div></body></html>